           id: "email",
           name: "email",
           label: "Email address",
           type: "email",
           autocomplete: "email",
           placeholder: "jamie@company.com",
           required: true,
           validationMessage: "Please enter a valid email address."
         }),
         FormField({
           id: "phone",
           name: "phone",
           label: "Phone number",
           type: "tel",
           autocomplete: "tel",
           inputMode: "tel",
           placeholder: "(555) 123-4567",
           hint: "Optional. Use a format like (555) 123-4567 or +1 555 123 4567.",
           validationMessage: "Use a phone number like (555) 123-4567 or +1 555 123 4567."
         })
       ];

       const validateField = (input) => {
         const error = form.querySelector(`#${input.id}-error`);
         let message = "";
         const trimmedValue = input.value.trim();

         if (input.name === "phone" && trimmedValue) {
           const phonePattern = /^\+?[0-9()\-\s]{7,20}$/;
           if (!phonePattern.test(trimmedValue)) {
             message = input.dataset.validationMessage;
           }
         } else if (!input.checkValidity()) {
           message = input.dataset.validationMessage || input.validationMessage;
         }

         error.textContent = message;
         error.hidden = !message;
         input.setAttribute("aria-invalid", message ? "true" : "false");
         return !message;
       };

       const inputs = fields.flatMap((field) => field.querySelectorAll("input"));
       inputs.forEach((input) => {
         input.addEventListener("blur", () => validateField(input));
         input.addEventListener("input", () => {
           const error = form.querySelector(`#${input.id}-error`);
           if (!error.hidden) {
             validateField(input);
           }
         });
       });

       form.addEventListener("submit", (event) => {
         event.preventDefault();
         const allValid = inputs.every((input) => validateField(input));

         status.hidden = true;
         status.textContent = "";

         if (allValid) {
           form.reset();
           inputs.forEach((input) => {
             input.setAttribute("aria-invalid", "false");
             const error = form.querySelector(`#${input.id}-error`);
             error.hidden = true;
             error.textContent = "";
           });
           status.textContent = "Your support request has been sent.";
           status.hidden = false;
         }
       });

       form.append(
         ...fields,
         createElement("div", { className: "submit-row" }, [
           SubmitButton(),
           createElement("p", {
             className: "privacy-note",
             text: "Required fields help our support team respond faster."
           })
         ]),
         status
       );

       return form;
     };

     const SupportPage = () =>
       createElement("main", { className: "page-shell" }, [
         createElement("section", { className: "support-card" }, [
           createElement("div", { className: "support-copy" }, [
             createElement("div", {}, [
               createElement("p", { className: "eyebrow", text: "Support" }),
               createElement("h1", { text: "Talk to our team about anything that needs attention." }),
               createElement("p", {
                 text: "Share a few details and we will route your request to the right specialist with the context they need."
               })
             ]),
             createElement("div", { className: "support-points" }, [
               SupportPoint({
                 title: "Fast routing",
                 description: "Required name and email fields ensure your message gets to the right person quickly."
               }),
               SupportPoint({
                 title: "Optional callback",
                 description: "Leave a phone number if you prefer a call for urgent or complex support needs."
               })
             ])
           ]),
           createElement("div", { className: "support-form-panel" }, [
             createElement("div", {}, [
               createElement("h2", { text: "Contact support" }),
               createElement("p", {
                 className: "intro",
                 text: "We usually reply within one business day."
               })
             ]),
             ContactForm()
           ])
         ])
       ]);

     document.getElementById("app").appendChild(SupportPage());
   </script>
 </body>
 </html>

')
